"""xformers.ops — iOS shim: memory_efficient_attention on torch SDPA.

Layout contract (matches real xformers):
  query/key/value: (batch, seqlen, nheads, headdim)  ["BMHK"]
  or 3-D (batch, seqlen, headdim) ["BMK"] — treated as 1 head.
attn_bias: None, an additive float tensor broadcastable to
  (batch, nheads, seq_q, seq_k), or LowerTriangularMask() for causal.
"""
import torch
import torch.nn.functional as F

__all__ = ["memory_efficient_attention", "AttentionBias",
           "LowerTriangularMask", "AttentionOpBase"]


class AttentionBias:
    """Base class — mirrors xformers.ops.AttentionBias."""


class LowerTriangularMask(AttentionBias):
    """Causal mask marker — mirrors xformers.ops.LowerTriangularMask."""


class AttentionOpBase:
    """Placeholder so `op=...` kwargs don't crash; the op choice is
    meaningless here (SDPA picks its own backend)."""


def memory_efficient_attention(query, key, value, attn_bias=None,
                               p=0.0, scale=None, op=None):
    squeeze_bmk = query.dim() == 3
    if squeeze_bmk:  # (B, M, K) -> (B, M, 1, K)
        query, key, value = (t.unsqueeze(2) for t in (query, key, value))

    q = query.transpose(1, 2)  # (B, H, S, D)
    k = key.transpose(1, 2)
    v = value.transpose(1, 2)
    if k.shape[1] != q.shape[1]:  # GQA/MQA
        rep = q.shape[1] // k.shape[1]
        k = k.repeat_interleave(rep, dim=1)
        v = v.repeat_interleave(rep, dim=1)

    kwargs = {"dropout_p": p}
    if scale is not None:
        kwargs["scale"] = scale
    if isinstance(attn_bias, LowerTriangularMask):
        out = F.scaled_dot_product_attention(q, k, v, is_causal=True, **kwargs)
    elif attn_bias is None:
        out = F.scaled_dot_product_attention(q, k, v, **kwargs)
    elif torch.is_tensor(attn_bias):
        out = F.scaled_dot_product_attention(q, k, v, attn_mask=attn_bias, **kwargs)
    else:
        raise NotImplementedError(
            f"xformers iOS shim: attn_bias type {type(attn_bias).__name__} "
            "is not supported (None, tensor, or LowerTriangularMask only)")

    out = out.transpose(1, 2)
    return out.squeeze(2) if squeeze_bmk else out


def __getattr__(name):
    raise AttributeError(
        f"xformers iOS shim: 'ops.{name}' is not implemented — only "
        "memory_efficient_attention / LowerTriangularMask are. Use torch's "
        "F.scaled_dot_product_attention directly (GPU via the Metal bridge).")
